from collections import Counter

class Solution:
    def minimumIncompatibility(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        m = n // k
        if max(Counter(nums).values()) > k:
            return -1
        best = float('inf')
        groups = [[] for _ in range(k)]

        def dfs(i, total):
            nonlocal best
            if total >= best:
                return
            if i == n:
                best = total
                return
            x = nums[i]
            seen = set()
            for g in groups:
                if len(g) < m and x not in g:
                    key = tuple(g)
                    if key in seen:
                        continue
                    seen.add(key)
                    g.append(x)
                    dfs(i + 1, total + (x - g[-2] if len(g) > 1 else 0))
                    g.pop()

        dfs(0, 0)
        return best

