class Solution {
public:
    int best;
    int n, m;
    vector<int> vals;

    void dfs(vector<vector<int>>& groups, int i, int total) {
        if (total >= best) return;
        if (i == n) { best = total; return; }
        int x = vals[i];
        set<vector<int>> seen;
        for (auto& g : groups) {
            if ((int)g.size() < m && find(g.begin(), g.end(), x) == g.end()) {
                if (seen.count(g)) continue;
                seen.insert(g);
                int add = g.empty() ? 0 : x - g.back();
                g.push_back(x);
                dfs(groups, i + 1, total + add);
                g.pop_back();
            }
        }
    }

    int minimumIncompatibility(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        vals = nums;
        n = nums.size();
        m = n / k;
        unordered_map<int, int> cnt;
        for (int x : nums) {
            if (++cnt[x] > k) return -1;
        }
        best = INT_MAX;
        vector<vector<int>> groups(k);
        dfs(groups, 0, 0);
        return best;
    }
};

