class Solution {
    private int best, n, m;
    private int[] nums;

    public int minimumIncompatibility(int[] nums, int k) {
        Arrays.sort(nums);
        this.nums = nums;
        n = nums.length;
        m = n / k;
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) {
            if (cnt.merge(x, 1, Integer::sum) > k) return -1;
        }
        best = Integer.MAX_VALUE;
        List<List<Integer>> groups = new ArrayList<>();
        for (int i = 0; i < k; i++) groups.add(new ArrayList<>());
        dfs(0, 0, groups);
        return best;
    }

    private void dfs(int i, int total, List<List<Integer>> groups) {
        if (total >= best) return;
        if (i == n) { best = total; return; }
        int x = nums[i];
        Set<List<Integer>> seen = new HashSet<>();
        for (List<Integer> g : groups) {
            if (g.size() < m && !g.contains(x)) {
                if (!seen.add(g)) continue;
                int add = g.isEmpty() ? 0 : x - g.get(g.size() - 1);
                g.add(x);
                dfs(i + 1, total + add, groups);
                g.remove(g.size() - 1);
            }
        }
    }
}

