from collections import Counter

class Solution:
    def minimumIncompatibility(self, nums: List[int], k: int) -> int:
        n = len(nums)
        m = n // k
        if max(Counter(nums).values()) > k:
            return -1
        nums.sort()
        full = (1 << n) - 1
        INF = float('inf')
        pc = [0] * (full + 1)
        for x in range(1, full + 1):
            pc[x] = pc[x >> 1] + (x & 1)
        cost = [-1] * (full + 1)
        for mask in range(full + 1):
            if pc[mask] != m:
                continue
            picked = [nums[i] for i in range(n) if mask >> i & 1]
            if len(set(picked)) == m:
                cost[mask] = picked[-1] - picked[0]
        dp = [INF] * (full + 1)
        dp[0] = 0
        for mask in range(full):
            if dp[mask] == INF:
                continue
            free = full ^ mask
            loBit = free & -free
            rest = free ^ loBit
            base = dp[mask]
            sub = rest
            while True:
                if pc[sub] == m - 1:
                    g = sub | loBit
                    c = cost[g]
                    if c >= 0 and base + c < dp[mask | g]:
                        dp[mask | g] = base + c
                if sub == 0:
                    break
                sub = (sub - 1) & rest
        return dp[full]

