class Solution {
public:
    int minimumIncompatibility(vector<int>& nums, int k) {
        int n = nums.size(), m = n / k;
        unordered_map<int, int> cnt;
        for (int x : nums) {
            if (++cnt[x] > k) return -1;
        }
        sort(nums.begin(), nums.end());
        int full = (1 << n) - 1;
        vector<int> cost(1 << n, -1);
        for (int mask = 0; mask <= full; mask++) {
            if (__builtin_popcount(mask) != m) continue;
            int mn = INT_MAX, mx = INT_MIN, last = -1;
            bool ok = true;
            for (int i = 0; i < n && ok; i++) {
                if (mask >> i & 1) {
                    if (last >= 0 && nums[i] == last) { ok = false; break; }
                    mn = min(mn, nums[i]);
                    mx = max(mx, nums[i]);
                    last = nums[i];
                }
            }
            if (ok) cost[mask] = mx - mn;
        }
        vector<int> dp(1 << n, INT_MAX);
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] == INT_MAX) continue;
            int free = full ^ mask;
            int i = __builtin_ctz(free);
            int rest = free ^ (1 << i);
            for (int sub = rest;; sub = (sub - 1) & rest) {
                if (__builtin_popcount(sub) == m - 1) {
                    int g = sub | (1 << i);
                    if (cost[g] >= 0 && dp[mask] + cost[g] < dp[mask | g]) {
                        dp[mask | g] = dp[mask] + cost[g];
                    }
                }
                if (sub == 0) break;
            }
        }
        return dp[full];
    }
};

