    const n = nums.length, m = n / k;
    const cnt = new Map();
    for (const x of nums) {
        const c = (cnt.get(x) || 0) + 1;
        if (c > k) return -1;
        cnt.set(x, c);
    }
    nums.sort((a, b) => a - b);
    const full = (1 << n) - 1;
    const pc = new Uint8Array(full + 1);
    for (let x = 1; x <= full; x++) pc[x] = pc[x >> 1] + (x & 1);
    const cost = new Int16Array(full + 1).fill(-1);
    for (let mask = 0; mask <= full; mask++) {
        if (pc[mask] !== m) continue;
        let mn = Infinity, mx = -Infinity, last = -1, ok = true;
        for (let i = 0; i < n; i++) {
            if (mask >> i & 1) {
                if (nums[i] === last) { ok = false; break; }
                if (nums[i] < mn) mn = nums[i];
                if (nums[i] > mx) mx = nums[i];
                last = nums[i];
            }
        }
        if (ok) cost[mask] = mx - mn;
    }
    const INF = 1e9;
    const dp = new Array(full + 1).fill(INF);
    dp[0] = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] === INF) continue;
        const free = full ^ mask;
        let i = 0;
        while (!(free >> i & 1)) i++;
        const loBit = 1 << i;
        const rest = free ^ loBit;
        const base = dp[mask];
        for (let sub = rest;; sub = (sub - 1) & rest) {
            if (pc[sub] === m - 1) {
                const g = sub | loBit;
                if (cost[g] >= 0 && base + cost[g] < dp[mask | g]) {
                    dp[mask | g] = base + cost[g];
                }
            }
            if (sub === 0) break;
        }
    }
    return dp[full];
};
